def get_components(grid):
    from collections import deque
    H, W = len(grid), len(grid[0])
    visited = set()
    components = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and (r, c) not in visited:
                comp = []
                color = grid[r][c]
                queue = deque([(r, c)])
                visited.add((r, c))
                while queue:
                    cr, cc = queue.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                components.append((color, comp))
    return components

def normalize_coords(coords):
    r_set = [r for r, c in coords]
    c_set = [c for r, c in coords]
    min_r, min_c = min(r_set), min(c_set)
    return sorted([(r - min_r, c - min_c) for r, c in coords])

def place_components(grid):
    out = [[0]*15 for _ in range(16)]
    H, W = 16, 15

    left = []
    right = []

    for color, coords in get_components(grid):
        norm = normalize_coords(coords)
        min_c = min(c for r, c in coords)
        if min_c < W/2:
            left.append((color, norm))
        else:
            right.append((color, norm))

    # Left: fill from top
    current_row = 0
    for color, norm in left:
        for cr, cc in norm:
            out[current_row + cr][cc] = color
        current_row += norm[-1][0] - norm[0][0] + 1

    # Right: fill from bottom
    row_counter = 15
    for color, norm in right:
        h = norm[-1][0] - norm[0][0] + 1
        for cr, cc in norm:
            out[row_counter - h + cr][cc] = color
        row_counter -= h

    return out

